package pe.edu.upeu.inscripcion.messaging; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; import org.springframework.transaction.support.TransactionSynchronization; import org.springframework.transaction.support.TransactionSynchronizationManager; import pe.edu.upeu.inscripcion.event.AcademicoEvento; @Component @RequiredArgsConstructor public class AcademicoEventosProducer {private final KafkaTemplate<String,Object> kafka; @Value("${app.kafka.topic.academico:kido-academico-eventos}") private String topic; public void publicarTrasCommit(AcademicoEvento e){Runnable r=()->kafka.send(topic,String.valueOf(e.getEstudianteId()),e);if(TransactionSynchronizationManager.isActualTransactionActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){r.run();}});else r.run();}}